# v13.34: Current Location in Add Entry
from playwright.sync_api import sync_playwright
CSV='/home/claude/Transactions.csv'; res=[]
def ok(n,c): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch(); errs=[]
    ctx=b.new_context(viewport={'width':390,'height':844},service_workers='block',geolocation={'latitude':35.5311,'longitude':139.6946},permissions=['geolocation']); pg=ctx.new_page()
    pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached')
    pg.set_input_files('#first-file',CSV); pg.wait_for_selector('#setup',timeout=20000); pg.click('#setup .btn'); pg.wait_for_timeout(900)
    pg.evaluate("(async()=>{const c=await import('/js/core.js');c.commit(d=>{d.settings.titleCase=false})})()")
    pg.evaluate("(async()=>{const m=await import('/js/entry.js');m.openEntry({})})()"); pg.wait_for_selector('#locrow'); pg.wait_for_timeout(500)
    ok('Current Location shown with permission line', 'Current Location' in pg.inner_text('#locrow') and 'Location permission' in pg.inner_text('#locrow'))
    y0=pg.evaluate("document.querySelector('#amountbox').getBoundingClientRect().top-document.querySelector('#seg').getBoundingClientRect().top")
    pg.click('#locrow [data-e=loc-get]'); pg.wait_for_timeout(900)
    t=pg.inner_text('#locrow'); ok('got the place %s'%t.replace('\n',' '), '35.53, 139.69' in t and 'allowed' in t)
    print('Y',y0,pg.evaluate("document.querySelector('#amountbox').getBoundingClientRect().top-document.querySelector('#seg').getBoundingClientRect().top"))
    ok('nothing above moved', abs(pg.evaluate("document.querySelector('#amountbox').getBoundingClientRect().top-document.querySelector('#seg').getBoundingClientRect().top")-y0)<1)
    pg.click('#locrow [data-e=loc-edit]'); pg.fill('#f-loc','35.6, 139.7'); pg.press('#f-loc','Tab'); pg.wait_for_timeout(200)
    ok('typed place used', '35.60, 139.70' in pg.inner_text('#locrow'))
    pg.fill('#f-amount','120'); pg.fill('#f-what','Loc test'); pg.click('#btns [data-e=save]'); pg.wait_for_timeout(700)
    r=pg.evaluate("(async()=>{const c=await import('/js/core.js');const t=c.get().txs.find(x=>x.name==='Loc test');return t&&t.loc})()"); ok('saved on the entry %s'%r, r and r['la']==35.6 and r['lo']==139.7)
    ctx2=b.new_context(viewport={'width':390,'height':844},service_workers='block'); q=ctx2.new_page(); q.goto('http://localhost:8123/'); q.wait_for_selector('#first-file',state='attached')
    q.set_input_files('#first-file',CSV); q.wait_for_selector('#setup',timeout=20000); q.click('#setup .btn'); q.wait_for_timeout(900)
    q.evaluate("(async()=>{const m=await import('/js/entry.js');m.openEntry({})})()"); q.wait_for_selector('#locrow'); q.wait_for_timeout(400)
    q.click('#locrow [data-e=loc-get]'); q.wait_for_timeout(1500)
    ok('no permission is explained %s'%q.inner_text('#locrow').replace('\n',' '), 'blocked' in q.inner_text('#locrow') or 'not available' in q.inner_text('#locrow') or 'Could not' in q.inner_text('#locrow'))
    ok('no errors %s'%errs, not errs)
    b.close()
print('fails',res.count(False))
